  "pf-apm-title": "Monitorização de Desempenho",
  "pf-apm-desc": "Métricas em tempo real de tempo de resposta, pedidos lentos e taxa de erros dos processadores de API instrumentados. Atualiza-se automaticamente a cada 15 segundos.",
  "pf-apm-loading": "A carregar as métricas de desempenho…",
  "pf-apm-load-failed": "Falha ao carregar as métricas de desempenho.",
  "pf-apm-no-data": "Ainda sem métricas. As métricas são registadas à medida que o tráfego passa pelos processadores de API instrumentados (produtos, parceiros, ofertas, faturas, pesquisa, gráficos do painel).",
  "pf-apm-updated": "Atualizado {when}",
  "pf-apm-uptime": "Tempo de atividade",
  "pf-apm-buffer-note": "A memória intermédia guarda os {n} pedidos mais recentes de {cap}.",
  "pf-apm-reset": "Repor métricas",
  "pf-apm-reset-confirm": "Limpar a memória intermédia de métricas? Esta ação não pode ser anulada.",
  "pf-apm-reset-done": "Memória intermédia de métricas limpa.",
  "pf-apm-reset-failed": "Falha ao limpar as métricas.",
  "pf-apm-kpi-total": "Total de Pedidos",
  "pf-apm-kpi-avg": "Tempo Médio de Resposta",
  "pf-apm-kpi-slow": "Pedidos Lentos",
  "pf-apm-kpi-slow-hint": "Pedidos que demoram mais de {ms} ms",
  "pf-apm-kpi-errors": "Taxa de Erros",
  "pf-apm-kpi-memory": "Memória (RSS)",
  "pf-apm-kpi-memory-hint": "Conjunto residente — memória total do processo",
  "pf-apm-kpi-heap": "Heap Utilizada",
  "pf-apm-kpi-heap-hint": "{used} MB de {total} MB alocados",
  "pf-apm-alerts-title": "Alertas Ativos",
  "pf-apm-no-alerts": "Sem alertas ativos — todas as métricas dentro dos limiares.",
  "pf-apm-chart-response-time": "Tempo de Resposta ao Longo do Tempo",
  "pf-apm-chart-response-time-desc": "Duração por pedido (ms) dos {n} pedidos mais recentes, do mais antigo para o mais recente.",
  "pf-apm-chart-volume": "Volume de Pedidos por Rota",
  "pf-apm-chart-volume-desc": "As 10 rotas com mais pedidos na memória intermédia atual.",
  "pf-apm-chart-errors": "Distribuição de Erros",
  "pf-apm-chart-errors-desc": "Proporção de pedidos por classe de estado HTTP.",
  "pf-apm-tab-slowest": "As 10 Rotas Mais Lentas",
  "pf-apm-tab-active": "As 10 Rotas Mais Ativas",
