  "ref-ag-s1-title": "1. Partes e objeto",
  "ref-ag-s1-body": "Este acordo estabelece a cooperação entre a empresa que opera esta plataforma e o parceiro de indicação: este apresenta empresas clientes e oportunidades de negócio e aufere uma comissão sobre os negócios concluídos com as empresas que indica.",
  "ref-ag-s2-title": "2. O seu papel como parceiro de indicação",
  "ref-ag-s2-l1": "Apresenta empresas clientes e oportunidades de negócio que representa ou com as quais tem uma relação genuína.",
  "ref-ag-s2-l2": "Confirma que tem liberdade para apresentar estas empresas e que o faz sem violar quaisquer obrigações para com terceiros.",
  "ref-ag-s2-l3": "A empresa que apresenta permanece a sua indicação: os negócios celebrados com ela geram a sua comissão nos termos abaixo definidos.",
