  "ref-ag-s3-body": "Pelos negócios celebrados com as empresas que indica, aufere uma comissão nos seguintes termos:",
  "ref-ag-s4-title": "4. Condições de pagamento",
  "ref-ag-s4-body": "A comissão torna-se exigível quando o negócio indicado é confirmado como concluído, todos os documentos exigidos são fornecidos e a comissão é aprovada. Os pagamentos são efetuados para a conta bancária que indicar em Dados de pagamento.",
  "ref-ag-s5-title": "5. Confidencialidade",
  "ref-ag-s5-body": "As condições deste acordo, a identidade das empresas indicadas e toda a informação comercial trocada são confidenciais e não podem ser divulgadas a terceiros.",
  "ref-ag-s6-title": "6. Duração e alterações",
  "ref-ag-s6-body": "O acordo aplica-se desde a aceitação até à rescisão por escrito. Sempre que as condições mudarem, é emitida uma nova versão, que exige a sua nova aceitação; a aceitação anterior permanece registada.",
