  "marketplace-dd-banner-title": "Negocie com segurança — faça a sua própria due diligence",
  "marketplace-dd-banner-short": "VELOS é um ponto de encontro neutro que liga compradores e vendedores. Não somos parte em nenhuma transação, não tratamos de bens nem de fundos e não aceitamos qualquer responsabilidade por negócios celebrados entre membros.",
  "marketplace-dd-banner-full": "Antes de se comprometer: verifique o registo e a reputação da contraparte, confirme licenças e certificados, exija pagamento seguro (depósito em garantia ou carta de crédito) e certifique-se de que a operação cumpre as leis que lhe são aplicáveis.",
  "marketplace-dd-open-safety": "Guia de segurança e conformidade",
  "marketplace-dd-show-more": "Mostrar mais",
  "marketplace-dd-show-less": "Mostrar menos",
  "marketplace-dd-panel-title": "Segurança e Conformidade",
  "marketplace-dd-panel-subtitle": "Orientações práticas de due diligence que todos os membros do marketplace devem seguir antes de enviar dinheiro ou mercadorias.",
  "marketplace-dd-panel-liability": "A VELOS fornece apenas apresentações e ferramentas. Não somos parte em nenhum contrato, não detemos nem movemos bens ou fundos, não certificamos a legalidade de nenhum anúncio e não aceitamos qualquer responsabilidade por perdas decorrentes de uma transação entre membros. Efetue sempre a sua própria due diligence e as suas verificações de conformidade.",
  "marketplace-dd-s1-title": "1. Verifique a contraparte",
  "marketplace-dd-s1-body": "Confirme o número de registo da empresa, o estado de VAT/EORI e a morada física nos registos oficiais. Na VELOS, prefira parceiros com o selo KYC Verificado — a identidade e os documentos foram analisados — e leia as avaliações de negócios anteriores. Uma chamada e uma visita por vídeo às instalações são um seguro barato.",
  "marketplace-dd-s2-title": "2. Garanta o pagamento",
  "marketplace-dd-s2-body": "Utilize depósito em garantia ou uma carta de crédito irrevogável com novas contrapartes; a VELOS suporta ambos. Evite transferências antecipadas em numerário para contas desconhecidas e nunca pague para contas bancárias pessoais. Alinhe o calendário de pagamentos com os marcos de entrega, para que nenhum montante elevado esteja em risco em qualquer momento.",
  "marketplace-dd-s3-title": "3. Verifique a mercadoria",
  "marketplace-dd-s3-body": "Solicite certificados de análise, especificações de qualidade e, quando aplicável, documentos de origem antes de contratar. Utilize inspeção pré-expedição (SGS, Bureau Veritas ou um agente de confiança) e mantenha o direito de recusar mercadorias que não correspondam às especificações acordadas.",
  "marketplace-dd-s4-title": "4. Formalize por escrito",
  "marketplace-dd-s4-body": "Assine um contrato de compra e venda adequado: especificação do produto, Incoterms 2020, calendário de entrega, condições de pagamento, direitos de inspeção, resolução de litígios e lei aplicável. Os modelos de documentos da VELOS e o histórico de negociação podem apoiar este processo, mas não substituem a sua própria revisão jurídica.",
  "marketplace-dd-s5-title": "5. Respeite as regras de conformidade",
  "marketplace-dd-s5-body": "As listas de sanções (UN, EU, OFAC), os controlos de exportação, as mercadorias de dupla utilização, as obrigações AML/KYC e as regras aduaneiras aplicam-se a si e à sua empresa. Garantir que uma operação planeada é legal para ambas as partes é responsabilidade sua — não da VELOS.",
  "marketplace-dd-s6-title": "6. Denuncie atividade suspeita",
  "marketplace-dd-s6-body": "Se um anúncio parecer fraudulento, enganoso ou proibido, denuncie-o com o botão Denunciar no anúncio. A nossa equipa analisa todas as denúncias. Se um negócio já correu mal, contacte de imediato o seu banco e envolva as autoridades da sua jurisdição — a VELOS pode apoiar as investigações com os dados que detém legalmente.",
  "marketplace-locked-tier-title": "A comunicação está bloqueada no seu nível",
  "marketplace-locked-tier-body": "Todos podem navegar neste marketplace, mas publicar, responder, negociar e licitar exige o nível Standard ou superior. Faça upgrade do seu nível de portal para desbloquear a comunicação.",
  "marketplace-locked-tier-body-respond": "Responder a este anúncio exige o nível Standard ou superior. Faça upgrade do seu nível de portal para enviar ofertas.",
  "marketplace-locked-tier-body-negotiate": "Enviar mensagens ou ofertas exige o nível Standard ou superior. Faça upgrade do seu nível de portal para continuar a negociação.",
  "marketplace-locked-tier-body-bid": "Colocar licitações exige o nível Standard ou superior. Faça upgrade do seu nível de portal para licitar em leilões.",
  "marketplace-locked-tier-body-qa": "Fazer ou responder a perguntas exige o nível Standard ou superior. Faça upgrade do seu nível de portal para participar na discussão.",
  "marketplace-locked-kyc-title": "Verificação KYC obrigatória",
  "marketplace-locked-kyc-body": "Para comunicar no marketplace, a sua análise KYC tem de estar totalmente aprovada — identidade, empresa e documentos bancários verificados. Conclua ou aguarde a sua análise KYC para desbloquear a publicação, as respostas e as licitações.",
  "marketplace-locked-kyc-body-respond": "A sua análise KYC tem de estar totalmente aprovada antes de poder responder a anúncios. Conclua ou aguarde a sua análise KYC.",
  "marketplace-locked-kyc-body-negotiate": "A sua análise KYC tem de estar totalmente aprovada antes de poder enviar mensagens ou ofertas. Conclua ou aguarde a sua análise KYC.",
  "marketplace-locked-kyc-body-bid": "A sua análise KYC tem de estar totalmente aprovada antes de poder colocar licitações. Conclua ou aguarde a sua análise KYC.",
  "marketplace-locked-kyc-body-qa": "A sua análise KYC tem de estar totalmente aprovada antes de poder fazer ou responder a perguntas. Conclua ou aguarde a sua análise KYC.",
  "marketplace-locked-upgrade-cta": "Pedir upgrade de nível",
  "marketplace-locked-kyc-cta": "Ir para a verificação KYC",
  "marketplace-dd-form-note": "A VELOS liga as partes comerciais, mas não é parte no seu negócio — verifique a contraparte, combine um pagamento seguro (depósito em garantia/L-C) e formalize as condições por escrito antes de se comprometer.",
